int main(){
    const char* t1 = "Tools-cpp is awsome!";
    const char* t2 = "v1.0";
    char t3[128];
    char t4[128];

    snprintf(t3, sizeof(t3), "%s Current verison is %s", t1, t2);
    snprintf(t4, sizeof(t4), " using compiler %s version %d with standard %ld", "Clang", 21, 202302L);
    strcat(t3, t4);

    char* First = &t3[0];
    char* Last = &t3[strlen(t3)-1];

    std::string tx = std::format("{}", t3);

    std::printf(
        "%s\n\n> That string above is %llu char long and took %llu bytes of your memory\n> Pointers are at 0x%p..0x%p",
        tx.c_str(),
        tx.length(),
        sizeof(tx.c_str()),
        First, Last
    );

    return 0;
}
